import './ui/style.css';
import * as R from './domain/run';
import {createBattle,stepBattle} from './domain/combat';
import {PAYLINES,PAYLINE_NAMES,RANK_NAMES} from './domain/slot';
import type {SlotIntervention} from './domain/slot';
import {UNITS,FAMILIES,RELICS,ITEMS,STATUSES,BUILDS,ENEMIES,EVENTS,XP_THRESHOLDS,FAMILY_COLORS,FAMILY_NAMES,getUnit,getRelic,getItem,getEnemy,getStats,levelForXp,makeUnit,specializationsFor} from './content';
import type {ActionResult,BattleState,FamilyId,NodeKind,UnitInstance} from './domain/types';
import {BattleRenderer} from './render/BattleRenderer';
import {familyIcon,icon,nodeIcon} from './ui/icons';
import {GameAudio} from './ui/audio';

const $=<T extends HTMLElement=HTMLElement>(selector:string)=>document.querySelector<T>(selector)!;
const esc=(s:unknown)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const n=(v:number)=>Math.round(v).toLocaleString('zh-CN');
const pct=(v:number)=>`${Math.round(v*100)}%`;
const attr=(data:Record<string,unknown>)=>Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ');
const btn=(label:string,action:string,data:Record<string,unknown>={},cls='',disabled=false,reason='')=>`<button class="btn ${cls}" data-action="${action}" ${attr(data)} ${disabled?'disabled':''} ${reason?`title="${esc(reason)}"`:''}>${label}</button>`;
const NODE_NAMES:Record<NodeKind,string>={normal:'据点',elite:'精英',boss:'城池首领',shop:'黑市',grave:'墓园',workshop:'邪术工坊',event:'怪事'};
const ACT_NAMES=['','村落边界','石墙城镇','沉眠王都'];
const SAVE_KEY='whitebone.save.v1',SETTINGS_KEY='whitebone.settings.v1';
const RULE_WORDS:Record<string,string>={BASIC_HIT:'普通攻击命中',DIRECT_CRIT:'直接暴击',DAMAGE_TAKEN:'实际生命受伤',EFFECTIVE_HEAL:'有效治疗',SHIELD_GAIN:'获得护盾',SHIELD_BREAK:'护盾破碎',CORPSE_CONSUME:'消耗尸骸',POISON_TICK:'尸毒跳伤',ALLY_KO:'友军倒地',ENEMY_KO:'敌军倒地',DASH_END:'冲锋结束',SUMMON:'召唤',TAUNTED:'嘲讽',TAUNT:'施加嘲讽',BONE_ARMOR:'骨甲',SOUL_BRAND:'收魂烙印',POISON:'尸毒',CHILL:'寒滞',FROZEN:'冰封',BURN:'尸焰',WET:'潮湿',SHOCK:'电荷',EXPOSED:'破绽',HASTE:'急速',REGEN:'再生',PHY:'物理',MAG:'法术',TRUE:'真实',APS:'攻速',ATK:'攻击',HP:'生命'};
const rule=(text:string)=>{let s=esc(text).replace(/\bR_[AM]\d{2}\b/g,id=>RELICS.find(r=>r.id===id)?.name||'遗物');for(const [k,v]of Object.entries(RULE_WORDS).sort((a,b)=>b[0].length-a[0].length))s=s.replace(new RegExp(`\\b${k}\\b`,'g'),v);return s};
const rarityName=(r:string)=>({common:'普通',rare:'稀有',legendary:'传奇'}[r]||r);
const phaseNames:Record<string,string>={map:'选择路线',prep:'招魂整军',battle:'自动交战',waveResult:'战后清点',reward:'选择战利品',shop:'黑市采购',grave:'墓园休整',workshop:'改造机器',event:'遭遇怪事',victory:'王都易主',defeat:'远征失败'};
interface Settings {muted:boolean;volume:number;speed:number;reduced:boolean;hints:boolean}
let settings:Settings={muted:false,volume:.22,speed:1,reduced:false,hints:true};
try{settings={...settings,...JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}')}}catch{}
const sound=new GameAudio();sound.muted=settings.muted;sound.volume=settings.volume;
let run:R.RunState|null=null,battle:BattleState|null=null,paused=false,modalOpen=false,spinningMs=0,accumulator=0,spinVisualTick=-1;
let selectedUid='',workbenchTab='army',starterId:R.StarterId='legion',mapSelection='',viewAct=1,codexFamily:FamilyId='SK',codexTab='units';
let selectedTool:R.InterventionOption|null=null,toolCells:number[]=[],sacrificeTarget='',lastFxId=0,lastLiveRefresh=0,lastSaveTime=0;
let branchChoices:Partial<Record<FamilyId,string>>={},currentModal='',newestToast=0,storageFailed=false;
let importedRun:R.RunState|null=null;
let savedText:string|null=null;try{savedText=localStorage.getItem(SAVE_KEY)}catch{}
let savedPreview=savedText?R.deserializeRun(savedText):null;
let seedDraft=new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+Math.floor(Math.random()*9999).toString().padStart(4,'0');
const coverTeam=[makeUnit('U_SK_3A','cover1',50,0),makeUnit('U_HR_2A','cover2',30,1),makeUnit('U_CF_2A','cover3',30,2),makeUnit('U_BL_2A','cover4',16,3)];

$('#app').innerHTML=`<div id="game-shell"><header id="hud"></header><main id="main"><section id="stage"><div id="world"></div><div id="stage-overlay"></div></section><section id="screen"></section></main><footer id="statusbar"></footer></div><div id="modal-layer" role="dialog" aria-modal="true"></div><input id="save-file-input" type="file" accept=".json,application/json" hidden/><div id="toast-area" class="toast-area" aria-live="polite"></div>`;
const renderer=new BattleRenderer($('#world'),{
 onUnitClick:id=>{if(!run)return;if(run.phase==='prep'){const u=R.findUnit(run,id);if(u)selectUnit(id)}else if(run.phase==='battle'){const u=battle?.units.find(x=>x.id===id);if(u?.sourceUid)showUnit(u.sourceUid);else if(u?.side==='ally'&&u.temporary)showTemporaryUnit(u.id);else if(u)showEnemy(u.templateId,u.id)}},
 onSlotClick:slot=>{if(run?.phase==='prep'&&selectedUid)act(()=>R.deployUnit(run!,selectedUid,slot))},
 onUnitDrop:(uid,slot)=>{if(run?.phase==='prep'){selectedUid=uid;act(()=>R.deployUnit(run!,uid,slot))}},
});

function toast(message:string,error=false){const id=++newestToast;$('#toast-area').innerHTML=`<div class="toast ${error?'error':''}">${esc(message)}</div>`;window.setTimeout(()=>{if(id===newestToast)$('#toast-area').innerHTML=''},3700)}
function persist(){try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings))}catch{}if(!run)return;try{const data=R.serializeRun(run,battle&&run.phase==='battle'?battle:undefined);localStorage.setItem(SAVE_KEY,data);savedText=data;localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));storageFailed=false}catch{if(!storageFailed)toast('浏览器无法保存。请保留当前窗口，避免丢失远征。',true);storageFailed=true}}
function act(action:()=>ActionResult,options:{close?:boolean;silent?:boolean}={}){if(!run)return;const result=action();if(result.ok){sound.play(result.sound||'confirm');if(options.close)closeModal();if(!options.silent&&result.message)toast(result.message);if(selectedUid&&!R.findUnit(run,selectedUid))selectedUid='';persist();render()}else{sound.play('deny');toast(result.message||'当前不能执行这个操作',true)}return result}
function openModal(title:string,body:string,footer='',wide=false){newestToast++;$('#toast-area').innerHTML='';modalOpen=true;$('#modal-layer').classList.add('open');$('#modal-layer').innerHTML=`<section class="modal ${wide?'wide':''}"><header class="modal-header"><h2>${esc(title)}</h2>${btn(icon('close'),'close-modal',{},'ghost icon-only')}</header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section>`;$('#modal-layer').querySelector<HTMLElement>('button')?.focus()}
function closeModal(){modalOpen=false;currentModal='';$('#modal-layer').classList.remove('open');$('#modal-layer').innerHTML=''}
function selectUnit(uid:string){if(sacrificeTarget&&uid!==sacrificeTarget){showSacrifice(uid,sacrificeTarget);return}selectedUid=uid;render()}
function allUnits(){return run?[...run.army,...run.staging]:[]}
function unitLocation(u:UnitInstance){const staged=run?.staging.findIndex(x=>x.uid===u.uid)??-1;if(staged>=0)return '待安置 '+(staged+1);return u.slot===null?'后备 '+((run?R.reserveUnits(run).findIndex(x=>x.uid===u.uid):-1)+1):'第'+(u.slot+1)+'阵位'}
function familyStyle(f:FamilyId){return `--family:${FAMILY_COLORS[f]}`}
function unitSelectOptions(selected=''){return (run?.army||[]).map(u=>`<option value="${u.uid}" ${selected===u.uid?'selected':''}>${esc(getUnit(u.templateId).name)} · ${unitLocation(u)} · R${getUnit(u.templateId).rank} / Lv${levelForXp(u.xp)}</option>`).join('')}
function familySelectOptions(families:FamilyId[],selected=''){return families.map(f=>`<option value="${f}" ${selected===f?'selected':''}>${FAMILY_NAMES[f]}</option>`).join('')}
function setStage(){const node=run?R.currentNode(run):null;renderer.setView({battle:run&&['battle','waveResult','victory','defeat'].includes(run.phase)?battle:null,team:run?R.deployedUnits(run):coverTeam,enemies:run?(run.phase==='victory'?[]:node?.waves[run.wave-1]||[]):[{templateId:'E01',count:4}],act:run?.act||1,phase:run?.phase||'title',selectedUid,capacity:run?.capacity||4,paused:paused||modalOpen});}
function render(){
 const phase=run?.phase||'title';$('#game-shell').className=`state-${phase} ${settings.reduced?'reduced-motion':''}`;
 renderHud();renderOverlay();
 const screen=$('#screen');
 if(!run)screen.innerHTML=titleScreen();
 else if(phase==='map')screen.innerHTML=mapScreen();
 else if(phase==='prep')screen.innerHTML=prepScreen();
 else if(phase==='battle')screen.innerHTML=battleControls();
 else if(phase==='waveResult')screen.innerHTML=waveResultScreen();
 else if(phase==='reward')screen.innerHTML=rewardScreen();
 else if(phase==='shop')screen.innerHTML=shopScreen();
 else if(phase==='grave')screen.innerHTML=graveScreen();
 else if(phase==='workshop')screen.innerHTML=workshopScreen();
 else if(phase==='event')screen.innerHTML=eventScreen();
 else screen.innerHTML=endScreen();
 $('#statusbar').innerHTML=`<span>${run?`种子 ${esc(run.seed)} · ${storageFailed?'保存失败':`${icon('check','sm')} 自动保存`}`:'死后照常营业 · 原型 v0.1'}</span><span>${run?'空格：主要操作 · F：全屏 · Esc：返回':'老虎机 × 死灵军团 × 随机远征'}</span>`;
 setStage();requestAnimationFrame(()=>renderer.resize());
}
function renderHud(){const phase=run?.phase||'title';$('#hud').innerHTML=`<div class="brand">${icon('skull')}<span>白骨开张</span></div>${run?`<div class="run-info"><span>第${run.act}章 · ${ACT_NAMES[run.act]}</span><span class="phase-indicator"><b>${phaseNames[phase]}</b></span></div><div class="hud-resources"><div class="resource hp" title="命匣归零，远征结束">${icon('heart')}<span id="hud-hp">${n(run.phase==='battle'&&battle?battle.phylacteryHp:run.hp)}<span> / ${run.maxHp}</span></span></div><div class="resource" title="招魂、扩军和购物共用的骨头">${icon('bones')}<span id="hud-bones">${n(run.bones)}</span></div></div>`:'<span class="spacer"></span>'}<div class="hud-tools">${run?btn(icon('shield'),'inventory',{},'ghost icon-only',false,'查看军团与遗物'):''}${btn(icon('book'),'codex',{},'ghost icon-only',false,'兵种与规则图鉴')}${btn(icon('event'),'help',{},'ghost icon-only',false,'玩法说明')}${btn(icon('settings'),'settings',{},'ghost icon-only',false,'设置与存档')}</div>`}
function renderOverlay(){if(!run){$('#stage-overlay').innerHTML='';return}const node=R.currentNode(run);if(!node||!['prep','battle','waveResult','reward','victory','defeat'].includes(run.phase)){$('#stage-overlay').innerHTML='';return}
 const live=battle&&run.phase==='battle';const alive=run.phase==='victory'?0:battle&&['battle','waveResult','defeat'].includes(run.phase)?battle.units.filter(u=>u.side==='enemy'&&u.alive).length:node.waves[run.wave-1]?.reduce((s,e)=>s+e.count,0)||0;
 $('#stage-overlay').innerHTML=`<div class="stage-title"><div class="eyebrow">${NODE_NAMES[node.kind]} · 第 ${run.wave} / 3 波</div><h2>${esc(node.name)}</h2><div class="small">${run.phase==='prep'?'战前准备 · 亡灵已满血复起':live?`${Math.floor(battle!.time)} 秒 · ${paused?'已暂停':'自动交战'}`:run.phase==='defeat'?'远征已结束，查看战报后可以重新开张。':run.phase==='victory'?'守军已散，今晚正式开张。':'敌人的尸骨，正好补齐下一班的工资。'}</div></div><div class="stage-enemies"><span class="stage-badge">${icon('sword','sm')} ${live?'敌军存活':run.phase==='prep'?'本波敌军':'敌军剩余'} ${alive}</span>${run.phase==='prep'?btn('查看敌情','enemy-preview',{},'compact'):''}${live?`<div class="combat-progress"><i style="width:${Math.max(0,100-battle!.time/battle!.timeLimit*100)}%"></i></div>`:''}</div>${run.phase==='prep'?`<div class="stage-hint">${selectedUid?'已选择 '+esc(getUnit(R.findUnit(run,selectedUid)?.templateId||'U_SK_1').name)+' · 点击阵位部署，或直接拖动战场单位':'前排承伤，后排支援 · 点击下方兵牌，再点阵位'}</div>`:''}${live?`<div class="live-log">${battle!.log.slice(-3).map(t=>`<span>${rule(t)}</span>`).join('')}</div>`:''}`;
}
function titleScreen(){return `<div class="title-layout"><div><div class="eyebrow">一场死后再就业的远征</div><div class="title-logo">白骨开张</div><p class="title-copy">摇出一身好骨头。<br>把随机的亡灵，组装成一支不讲道理的军队。</p><div class="title-divider"></div><p class="muted small">每次拉杆决定谁来上岗。<br>每一次搭配，决定他们能闹出多大动静。</p><div class="title-meta"><span>三章 · 36 波</span><span>6 族 · 36 职业</span><span>随时保存</span></div></div><section class="start-panel"><div class="row between"><h3>今晚，你招哪一班？</h3><span class="badge">完整远征</span></div><div class="starter-list">${R.STARTERS.map((s,i)=>`<button class="starter-card ${starterId===s.id?'active':''}" data-action="select-starter" data-id="${s.id}">${familyIcon((['SK','ZM','HR'] as FamilyId[])[i])}<div><strong>${s.name}</strong><p>${esc(s.description)}</p></div></button>`).join('')}</div><label class="seed-input"><span>远征种子</span><input id="seed-input" value="${esc(seedDraft)}" maxlength="40" aria-label="远征种子"/></label>${btn('开张，出发 '+icon('arrow'),'new-run',{},'primary wide')}${savedPreview?`<div style="margin-top:12px">${btn(`继续上次 · 第${savedPreview.act}章 / 已过${savedPreview.runStats.wavesWon}波`,'continue-run',{},'wide')}</div>`:''}<p class="small muted" style="margin-top:16px">首局目标 30–45 分钟。可随时退出，下次接着开张。</p></section></div>`}
function mapScreen(){const r=run!,act=Math.max(1,Math.min(3,viewAct)),nodes=r.map.filter(x=>x.act===act),avail=R.availableNodes(r);let selected=nodes.find(x=>x.id===mapSelection)||avail.find(x=>x.act===act)||nodes.find(x=>x.id===r.currentNodeId)||nodes[0];mapSelection=selected?.id||'';
 const coords=(node:R.MapNode)=>({x:7+(node.layer-1)*14.3,y:node.kind==='boss'?50:20+node.lane*30});
 const paths=nodes.flatMap(a=>a.links.map(id=>({a,b:nodes.find(x=>x.id===id)}))).filter(x=>x.b).map(({a,b})=>{const p=coords(a),q=coords(b!);return `<path class="${a.completed&&b!.visited?'traversed':a.id===r.currentNodeId?'next':''}" d="M${p.x} ${p.y} C${p.x+6} ${p.y},${q.x-6} ${q.y},${q.x} ${q.y}" vector-effect="non-scaling-stroke"/>`}).join('');
 const selectedAvailable=avail.some(x=>x.id===selected?.id);
 return `<div class="full-screen"><header class="screen-title"><div><div class="eyebrow">死灵远征 · 第 ${act} 章</div><h1>${ACT_NAMES[act]}</h1><p>下一条路，决定下一班员工的命运。</p></div><div class="act-tabs">${[1,2,3].map(a=>`<button class="act-tab ${act===a?'active':''}" data-action="view-act" data-act="${a}">${a<r.act?'✓ ':''}${a}. ${ACT_NAMES[a]}</button>`).join('')}</div></header><div class="map-layout"><div><div class="map-board"><svg class="map-paths" viewBox="0 0 100 100" preserveAspectRatio="none">${paths}</svg>${nodes.map(node=>{const p=coords(node),available=avail.some(x=>x.id===node.id);return `<button class="map-node ${node.kind} ${available?'available':''} ${node.visited?'visited':''} ${node.id===r.currentNodeId?'current':''} ${node.id===selected?.id?'selected':''}" style="left:${p.x}%;top:${p.y}%" data-action="inspect-node" data-id="${node.id}" aria-label="${node.name} ${available?'可以前往':'查看'}"><span class="node-circle">${node.completed?icon('check'):nodeIcon(node.kind)}</span><span class="node-label">${NODE_NAMES[node.kind]}</span></button>`}).join('')}</div><div class="map-legend">${(['normal','elite','boss','shop','grave','workshop','event'] as NodeKind[]).map(k=>`<span>${nodeIcon(k)}${NODE_NAMES[k]}</span>`).join('')}</div></div><aside class="node-detail"><div class="detail-icon">${selected?nodeIcon(selected.kind):''}</div><div><div class="eyebrow">${selected?.visited?'已走过的路':selectedAvailable?'可选择的下一站':'路线预览'}</div><h3 style="margin-top:8px">${esc(selected?.name||'选择一个节点')}</h3></div><p>${esc(selected?.preview||'')}</p><div class="reward-preview">${icon('spark','sm')} ${esc(selected?.rewardPreview||'')}</div>${selected?.kind==='boss'?'<p class="small danger-text">首领三波必须连胜；任一波失败会结束远征。</p>':''}<span class="spacer"></span>${btn(`${selectedAvailable?'前往':'尚未连接'} ${selected?NODE_NAMES[selected.kind]:''} ${icon('arrow','sm')}`,'enter-node',{id:selected?.id||''},selectedAvailable?'primary wide':'wide',!selectedAvailable,selectedAvailable?'':'选择与你当前位置相连的发光节点')}</aside></div><div class="journey-progress"><span>已占领 <strong>${r.runStats.nodesCompleted}</strong> 个节点</span><span>战斗 <strong>${r.runStats.wavesWon} / 36</strong> 波</span><span>军团 <strong>${R.deployedUnits(r).length} / ${r.capacity}</strong></span><span class="spacer"></span>${btn('整理军团','inventory',{},'compact')}${btn('保存并返回标题','title',{},'ghost compact')}</div></div>`;
}
function unitCard(u:UnitInstance,staged=false){const d=getUnit(u.templateId),level=levelForXp(u.xp),next=level<8?XP_THRESHOLDS[level]:150,prev=XP_THRESHOLDS[level-1],progress=level===8?100:(u.xp-prev)/(next-prev)*100;return `<button class="unit-card rank-${d.rank} ${selectedUid===u.uid?'selected':''} ${staged?'staged':''} ${u.slot===null&&!staged?'benched':''}" style="${familyStyle(d.family)};--xp:${progress}%" data-action="select-unit" data-uid="${u.uid}" draggable="true" data-drag-unit="${u.uid}"><span class="family-symbol">${familyIcon(d.family)}</span><div class="unit-copy"><span class="rank-badge">${RANK_NAMES[d.rank]} R${d.rank} · Lv${level}</span><strong>${esc(d.name)}</strong><p>${Math.round(getStats(u).hp)} 生命 · ${Math.round(getStats(u).atk)} 攻击</p></div>${staged?'<span class="unit-tag">待安置</span>':level>=4&&!u.specialization?'<span class="unit-tag">可专精</span>':''}<span class="xp-line"></span></button>`}
function prepScreen(){const r=run!,cost=R.spinCost(r),pending=!!r.slot&&!r.slot.settled,wins=R.getSlotWins(r);const board=r.slot?.board||Array.from({length:9},(_,i)=>r.familyWeights[[0,1,2,3,2,0,1,3,2][i]].family);const winning=new Set(wins.flatMap(w=>w.lines.flatMap(i=>[...PAYLINES[i]])));
 const tools=R.interventionOptions(r).map(uiTool).filter(x=>r.machineRelics.includes(x.sourceId)||(r.items[x.sourceId]||0)>0);
 const lines=pending&&spinningMs<=0?wins.flatMap(w=>w.lines.map(i=>{const line=PAYLINES[i],a=line[0],b=line[2];return `<line x1="${(a%3+.5)*33.33}%" y1="${(Math.floor(a/3)+.5)*33.33}%" x2="${(b%3+.5)*33.33}%" y2="${(Math.floor(b/3)+.5)*33.33}%"/>`})).join(''):'';
 let primaryLabel='',primaryAction='',primaryDisabled=false;
 if(spinningMs>0){primaryLabel='招魂中…';primaryAction='noop';primaryDisabled=true}else if(pending){primaryLabel=wins.length?'查看招魂结果 '+icon('arrow','sm'):'空盘 · 收起结果';primaryAction='claim-dialog'}else{primaryLabel=cost===0?'免费拉杆 '+icon('spark','sm'):cost===null?'本波抽取已用完':`再摇一次 · ${cost} ${icon('bones','sm')}`;primaryAction='spin';primaryDisabled=cost===null||r.bones<(cost||0)}
 const selected=R.findUnit(r,selectedUid);const can=R.canStartWave(r);const pendingSpecs=R.pendingSpecializations(r).filter(u=>u.slot!==null);const deployed=R.deployedUnits(r);const bench=R.reserveUnits(r);
 let content='';
 if(workbenchTab==='army')content=`${r.staging.length?`<div class="tip-banner" style="margin-bottom:8px">${icon('spark')}新员工 ${r.staging.length} 名。${deployed.length<r.capacity?'选中兵牌，再点空阵位。':'拖到阵位可替换。'}${bench.length>=8?'后备已满，可以吸收或换壳。':'也可放入后备或吸收。'}</div>`:''}<div class="unit-grid">${r.staging.map(u=>unitCard(u,true)).join('')}${deployed.map(u=>unitCard(u)).join('')}${Array.from({length:Math.max(0,r.capacity-deployed.length)},(_,i)=>`<button class="unit-empty" data-action="deploy-selected" data-slot="${Array.from({length:r.capacity},(_,k)=>k).filter(k=>!deployed.some(u=>u.slot===k))[i]}">${icon('check','sm')}空阵位</button>`).join('')}</div>${bench.length?`<div class="bench-line"><span class="small muted">后备 ${bench.length}/8</span>${bench.map(u=>`<button class="bench-chip ${selectedUid===u.uid?'selected':''}" data-action="select-unit" data-uid="${u.uid}" style="${familyStyle(getUnit(u.templateId).family)}">${familyIcon(getUnit(u.templateId).family)}${esc(getUnit(u.templateId).name)} <span class="rank-badge">R${getUnit(u.templateId).rank}</span></button>`).join('')}</div>`:''}`;
 else if(workbenchTab==='relics')content=`<div class="relic-grid">${[...r.machineRelics,...r.armyRelics].map(id=>{const d=getRelic(id);return `<button class="mini-relic" data-action="relic-info" data-id="${id}">${icon(d.type==='machine'?'wrench':'spark')}<div><strong>${d.name}</strong><p>${d.type==='machine'?'机器':'军团'} · ${rarityName(d.rarity)}</p></div></button>`}).join('')}</div><div class="row between" style="margin-top:12px"><span class="small muted">机器 ${r.machineRelics.length}/${r.machineCapacity} · 军团 ${r.armyRelics.length}/${r.armyRelicCapacity}</span>${btn('查看遗物库'+(R.unequippedRelics(r).length?` (${R.unequippedRelics(r).length}待装)`:''),'relic-inventory',{},'compact')}</div>`;
 else content=`<div class="item-grid">${Object.entries(r.items).filter(([,count])=>count>0).map(([id,count])=>{const d=getItem(id);return `<div class="item-card"><h3>${d.name} ×${count}</h3><p>${rule(d.effect)}</p>${btn('使用道具','item-dialog',{id},'compact')}</div>`}).join('')}</div>${!Object.keys(r.items).length?'<div class="empty">道具袋还空着。黑市和事件能带回新的歪点子。</div>':''}${r.waveState.queuedFamily||r.waveState.queuedOil?`<div class="row between small" style="margin-top:12px"><span class="gold">下次拉杆预备：${r.waveState.queuedFamily?FAMILY_NAMES[r.waveState.queuedFamily]+'引魂券 ':''}${r.waveState.queuedOil?'骨脂':''}</span>${btn('取消预备','cancel-queued-items',{},'compact')}</div>`:''}<p class="small muted" style="margin-top:8px">本波已用 ${r.waveState.itemUses}/2 份 · 最多3种道具，每种叠3份</p>`;
 return `<div class="prep-dock"><section class="machine"><div class="machine-core"><div class="machine-top"><span class="machine-title">招魂老虎机</span>${btn('概率','weights-info',{},'ghost compact')}</div>${selectedTool?`<div class="tool-hint">${toolHint()} ${btn('取消','cancel-tool',{},'ghost compact')}</div>`:''}<div class="slot-wrapper"><div class="slot-grid">${board.map((f,i)=>`<button class="slot-cell ${pending&&winning.has(i)&&spinningMs<=0?'winning':''} ${toolCells.includes(i)?'picked':''} ${spinningMs>0?'spinning':''}" data-action="slot-cell" data-index="${i}" aria-label="第${Math.floor(i/3)+1}行第${i%3+1}列 ${FAMILY_NAMES[f]}" ${!selectedTool?'tabindex="-1"':''}>${familyIcon(f)}<span class="cell-position">${i+1}</span></button>`).join('')}</div><svg class="slot-lines">${lines}</svg></div>${btn(primaryLabel,primaryAction,{},`primary machine-primary ${cost===0&&!pending?'ready':''}`,primaryDisabled)}<div class="machine-smallprint"><span>${r.waveState.spins===0?'本波免费 1 次':`追加 ${r.waveState.paidSpins}/${r.machineRelics.includes('R_M18')?5:3}`}</span><span>干预 ${r.slot?.interventions||0}/2</span></div></div><div class="machine-tools">${tools.slice(0,5).map(t=>`<button class="machine-tool ${selectedTool?.sourceId===t.sourceId?'selected':''}" data-action="select-tool" data-source="${t.sourceId}" ${!pending||!t.available||spinningMs>0?'disabled':''} title="${esc(t.reason||t.label)}">${icon(t.kind==='lockColumn'?'lock':'wrench')}<span>${shortToolName(t.kind)}</span><span class="small">${t.cost?`${t.cost}骨`:'免费'}</span></button>`).join('')}${r.machineRelics.includes('R_M17')&&!r.nodeState.machineLocked?btn('配重','temp-weight',{},'compact'):''}</div></section><section class="army-workbench"><header class="workbench-heading"><div class="tabs"><button class="tab ${workbenchTab==='army'?'active':''}" data-action="tab" data-tab="army">军团 <span class="count">${deployed.length}/${r.capacity}</span></button><button class="tab ${workbenchTab==='relics'?'active':''}" data-action="tab" data-tab="relics">遗物 <span class="count">${r.ownedRelics.length}</span></button><button class="tab ${workbenchTab==='items'?'active':''}" data-action="tab" data-tab="items">道具 <span class="count">${Object.values(r.items).reduce((a,b)=>a+b,0)}</span></button></div>${R.expansionCost(r)!==null?btn(`扩军 +1 · ${R.expansionCost(r)}骨`,'expand',{},'compact',r.bones<R.expansionCost(r)!,'增加一名正式上阵容量'): '<span class="badge success">军团已满编</span>'}</header><div class="army-content">${content}</div>${workbenchTab==='army'?`<div class="army-actions"><span class="selection-hint">${sacrificeTarget?`正在给 ${esc(getUnit(R.findUnit(r,sacrificeTarget)!.templateId).name)} 吸收 · 选择供体`:selected?`已选：${esc(getUnit(selected.templateId).name)}`:'点击兵牌查看，拖到阵位部署'}</span>${sacrificeTarget?btn('取消吸收','cancel-sacrifice',{},'compact'):selected?`${btn('详情','unit-info',{uid:selected.uid},'compact')}${btn(selected.slot===null?'部署':'后备',selected.slot===null?'auto-deploy':'bench',{uid:selected.uid},'compact')}${r.staging.some(u=>u.uid===selected.uid)?btn('存后备','bench',{uid:selected.uid},'compact'):''}${btn('吸收','sacrifice-mode',{uid:selected.uid},'compact')}${levelForXp(selected.xp)>=4&&!selected.specialization?btn('选专精','spec-dialog',{uid:selected.uid},'compact primary'):''}`:''}</div>`:''}<div class="primary-flow"><div class="flow-hint">${icon(can.ok?'check':'event','sm')}<span>${can.ok?'阵容就绪。让他们上岗。':pending?(wins.length?`已有${wins.length}名可招募。确认前仍可改盘。`:'还没有连线。可改盘试试，也能收起空盘直接开战。'):pendingSpecs.length&&!pending&&r.staging.length===0?`${pendingSpecs.length}名士兵已到Lv4，选择专精后开战。`:esc(can.message||'')}</span></div>${pendingSpecs.length&&!pending&&r.staging.length===0?btn('选择训练专精','spec-dialog',{uid:pendingSpecs[0].uid},'primary start-battle'):btn('进攻 · 第'+r.wave+'波 '+icon('sword','sm'),'start-battle',{},'primary start-battle',!can.ok||spinningMs>0,can.message)}</div></section></div>`;
}
function uiTool(t:R.InterventionOption):R.InterventionOption{return t.sourceId==='R_M08'?{...t,kind:'copyCenter'}:t}
function shortToolName(kind:string){return ({lockColumn:'锁列',swap:'换格',copy:'抄骨',rotateColumn:'转列',swapColumns:'换列',rotateCorners:'四角',copyCenter:'摄魂',rerollRow:'重摇行',rerollCell:'重摇格'} as Record<string,string>)[kind]||'改盘'}
function toolHint(){if(!selectedTool)return '';const k=selectedTool.kind;return ({lockColumn:'点击要保留的那一列',rotateColumn:'点击要循环转动的列',swapColumns:toolCells.length?'再选另一列':'选择第一列',rerollRow:'点击要重摇的横排',rotateCorners:'点击任意格，转动四角',copyCenter:'点一个非中央格，复制到中央',rerollCell:'点击要重摇的一格',swap:toolCells.length?'再选相邻的第二格':'点击第一格',copy:toolCells.length?'点击要覆盖的相邻格':'点击要复制的来源格'} as Record<string,string>)[k]||'选择盘面格子'}
function battleControls(){const b=battle!;return `<div class="battle-controls"><span class="badge ${paused?'new':'success'}">${paused?'暂停中':'正在自动交战'}</span><div class="battle-metrics"><span>伤害 <b id="live-damage">${n(b.stats.damage)}</b></span><span>治疗 <b id="live-heal">${n(b.stats.healing)}</b></span><span>召唤 <b id="live-summons">${b.stats.summons}</b></span></div><span class="spacer"></span>${btn(`${settings.speed}× 速度`,'speed',{},'compact')}${btn(icon(paused?'play':'pause')+(paused?'恢复':'暂停'),'pause',{},'compact')}${Object.keys(run!.items).some(id=>id==='I11'||id==='I12')?btn('战中道具','combat-items',{},'compact'):''}</div>`}
function topStats(){const values=Object.values(run!.battleResult?.stats.unitStats||{}).sort((a,b)=>b.damage-a.damage).slice(0,4);const max=Math.max(1,...values.map(x=>x.damage));return `<div class="stat-bar-list">${values.map(x=>`<div class="stat-bar-row"><span>${esc(x.name)}</span><span class="stat-bar-bg"><i style="width:${x.damage/max*100}%"></i></span><b>${n(x.damage)}</b></div>`).join('')}</div>`}
function waveResultScreen(){const r=run!,s=r.battleResult;if(!s)return '<div class="empty">战报整理中…</div>';const won=s.result==='win',lost=s.result==='loss';const combos=comboEntries(s.stats.comboCounts).slice(0,3);return `<div class="wave-result"><div><div class="result-stamp">${icon(won?'crown':'shield')}<div><h2>${won?s.nodeComplete?'据点拿下':'本波过关':lost?'远征失败':'撤出防线'}</h2><p>${esc(lost?defeatReason():s.message)}</p></div></div><div class="result-totals"><div><b>+${s.bones}</b><span>骨头入账</span></div><div><b class="${s.hpLost?'danger-text':''}">${s.hpLost?'-'+s.hpLost:'无损'}</b><span>命匣损失</span></div><div><b>${Math.round(s.duration)}s</b><span>交战时间</span></div></div></div><div>${topStats()}<div class="combo-strip">${s.stats.summons?`<span>临时召唤 ${s.stats.summons}</span>`:''}${s.stats.healing?`<span>有效治疗 ${n(s.stats.healing)}</span>`:''}${combos.map(([key,value])=>`<span>${comboLabel(key)} ×${value}</span>`).join('')}</div></div><div class="stack">${btn(s.nodeComplete?'挑选战利品 '+icon('spark','sm'):won?'准备下一波 '+icon('arrow','sm'):lost?'查看本次远征 '+icon('arrow','sm'):'离开据点 '+icon('arrow','sm'),'continue-wave',{},'primary wide')}${btn('查看完整战报','battle-report',{},'ghost compact')}</div></div>`}
function relicCard(id:string,action:string,data:Record<string,unknown>,label:string,disabled=false){const d=getRelic(id);return `<article class="offer-card ${d.rarity}"><div class="row between"><span class="badge">${d.type==='machine'?'机器零件':'军团遗物'}</span><span class="rank-badge ${d.rarity==='legendary'?'gold':''}">${rarityName(d.rarity)}</span></div><div class="offer-icon">${icon(d.type==='machine'?'wrench':'spark')}</div><h3>${esc(d.name)}</h3><p>${rule(d.effect)}</p><div class="limit">${rule(d.trigger)}</div><div class="row between">${btn('详情','relic-info',{id},'ghost compact')}${btn(label,action,data,'primary',disabled)}</div></article>`}
function rewardScreen(){const r=run!,node=R.currentNode(r)!;return `<div class="reward-screen"><header class="screen-title"><div><div class="eyebrow">占领奖励 · 只能选择一件</div><h2>${node.kind==='boss'?'新章开始，好戏加码。':'从战利品里，挑一个坏点子。'}</h2><p>遗物改变打法。合适的那件，比单纯更贵的那件重要。</p></div><span class="badge success">据点奖金已入账</span></header><div class="reward-grid">${r.rewardChoices.map(c=>c.kind==='relic'?relicCard(c.relicId!,'take-reward',{id:c.id},'带走这件'): `<article class="offer-card"><div class="offer-icon">${icon('bones')}</div><h3>回收剩余骨头</h3><p>这个档位的可用遗物不足。将战利品折算为${c.amount}根骨头。</p>${btn('领取 '+c.amount+' 骨','take-reward',{id:c.id},'primary')}</article>`).join('')}</div><div class="reward-footer">${node.kind==='normal'?btn('放弃三选一，换一张引魂券','take-reward',{id:'voucher'},'compact'):''}${btn('放弃奖励，继续远征','take-reward',{id:'skip'},'ghost compact')}</div></div>`}
function serviceHeading(eyebrow:string,title:string,copy:string){return `<header class="screen-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div>${btn('军团与遗物','inventory',{},'compact')}</header>`}
function serviceFooter(){return `<div class="service-actions"><span class="small muted">${run!.nodeState.serviceUsed?'本次服务已完成。':'不满意也可以空手离开。'} 已有兵种不会因改造轮盘消失。</span>${btn('返回路线 '+icon('arrow','sm'),'leave-service',{},'primary')}</div>`}
function shopScreen(){const r=run!,refresh=R.refreshCost(r);return `<div class="full-screen">${serviceHeading('黑市 · 只收骨头，不开发票','亡者也要货比三家。','库存随这次远征固定；刷新有成本。花在这里的骨头，就不能拿去追下一盘大奖。')}<div class="service-layout"><div class="shop-grid">${r.shopStock.map(o=>{if(o.kind==='relic')return relicCard(o.contentId,'buy',{id:o.id},o.sold?'已售出':`${o.price} 骨 · 买下`,o.sold||r.bones<o.price);const d=getItem(o.contentId);return `<article class="offer-card ${o.sold?'sold':''}"><div class="row between"><span class="badge">一次性道具</span><span class="small muted">${esc(d.use_phase)}</span></div><div class="offer-icon">${icon('spark')}</div><h3>${d.name}</h3><p>${rule(d.effect)}</p>${btn(o.sold?'已售出':`${o.price} 骨 · 买下`,'buy',{id:o.id},'primary',o.sold||r.bones<o.price)}</article>`}).join('')}</div><aside class="service-aside"><h3>柜台服务</h3><p>为下一场准备一点确定性。</p>${btn(refresh===null?'刷新次数已用完':`刷新库存 · ${refresh}骨`,'refresh-shop',{},'wide',refresh===null||r.bones<(refresh||0))}<div class="divider"></div><h3>微调权重</h3><p>支付4骨，将1份概率从一族移给另一族。每次黑市一次。</p><label class="select-field">转出<select id="shop-from">${familySelectOptions(r.familyWeights.map(x=>x.family))}</select></label><label class="select-field">转入<select id="shop-to">${familySelectOptions(r.familyWeights.map(x=>x.family),r.familyWeights[1].family)}</select></label>${btn('永久微调 · 4骨','shop-weight',{},'wide',r.nodeState.shopWeightUsed||r.bones<4)}<div class="divider"></div>${R.expansionCost(r)!==null?btn(`扩军 +1 · ${R.expansionCost(r)}骨`,'expand',{},'wide',r.bones<R.expansionCost(r)!):'<span class="badge success">8人编制已开满</span>'}</aside></div>${serviceFooter()}</div>`}
function graveScreen(){const r=run!;return `<div class="full-screen">${serviceHeading('墓园 · 终于有个不用花钱的地方','休息，是为了更好地返岗。','免费选择一项：修补你的命匣，或者让一名亡灵参加岗前培训。')}<div class="large-choice-grid"><section class="large-choice">${icon('heart')}<h2>修补命匣</h2><p>恢复15点命匣，最高${r.maxHp}。现在 ${r.hp}/${r.maxHp}。</p><span class="spacer"></span>${btn(r.hp===r.maxHp?'命匣完好':'恢复 '+Math.min(15,r.maxHp-r.hp)+' 点','grave-heal',{},'primary wide',r.nodeState.serviceUsed||r.hp===r.maxHp)}</section><section class="large-choice">${icon('book')}<h2>岗前培训</h2><p>指定一名正式兵获得12训练经验。提高训练，不改变出生阶级。</p><label class="select-field">参加培训的亡灵<select id="grave-target">${unitSelectOptions(selectedUid)}</select></label>${btn('参加培训 · +12经验','grave-train',{},'primary wide',r.nodeState.serviceUsed)}</section></div>${serviceFooter()}</div>`}
function workshopScreen(){const r=run!,active=r.familyWeights.map(x=>x.family),inactive=FAMILIES.map(x=>x.id).filter(x=>!active.includes(x));return `<div class="full-screen">${serviceHeading('邪术工坊 · 理论上符合概率学','把运气，拧向你需要的那一边。','每次只做一项改造。权重总计20份，单族最低2、最高10；已有军队保持不变。')}<div class="service-layout"><section class="large-choice" style="max-width:740px"><div class="row between"><h2>重新配重</h2><span class="badge">一次 6骨</span></div><p>倾向一族更容易开高阶，但会减少其他族的支援供给。</p><div class="weight-list">${r.familyWeights.map(w=>`<label class="weight-row" style="${familyStyle(w.family)}">${familyIcon(w.family)}<strong>${FAMILY_NAMES[w.family]}</strong><input class="weight-input" data-family="${w.family}" type="number" min="2" max="10" step="1" value="${w.weight}"/><span data-weight-pct="${w.family}">${w.weight*5}%</span></label>`).join('')}</div><div class="row between"><span id="weight-total" class="small muted">合计20份 · 配重合法</span>${btn('提交新配重 · 6骨','apply-weights',{},'primary',r.nodeState.serviceUsed||r.bones<6)}</div></section><aside class="service-aside"><h3>替换符号家族</h3><p>花8骨换掉一族符号，继承原权重。旧兵不会消失，新盘开始招募新家族。</p><label class="select-field">替换谁<select id="family-from">${familySelectOptions(active)}</select></label><label class="select-field">换成谁<select id="family-to">${familySelectOptions(inactive)}</select></label>${btn('更换符号 · 8骨','replace-family',{},'wide',r.nodeState.serviceUsed||r.bones<8)}${btn('查看六族职业','codex',{},'ghost compact')}</aside></div>${serviceFooter()}</div>`}
function eventScreen(){const r=run!,e=EVENTS.find(x=>x.id===r.eventId)!;return `<div class="full-screen">${serviceHeading('黑色幽默事件 · 一次选择',e?.name||'一件怪事','按钮上的代价与收益，就是这次交易的全部条款。')}<div class="event-layout"><div class="event-portrait">${icon(e?.id==='EV07'?'wrench':e?.id==='EV08'?'crown':'skull')}</div><div><p class="event-story">${esc(e?.setup)}</p>${['EV01','EV03','EV04'].includes(e?.id)?`<label class="select-field" style="margin-bottom:16px">如果选择训练，受益者为<select id="event-target">${unitSelectOptions(selectedUid)}</select></label>`:''}${e?.id==='EV06'?'<div class="tip-banner" style="margin-bottom:16px">团建优先给经验最低的三名未满级正式兵，各6经验。</div>':''}${e?.id==='EV07'?`<div class="form-row" style="margin-bottom:16px"><label class="select-field">权重转出<select id="event-from">${familySelectOptions(r.familyWeights.map(x=>x.family))}</select></label><label class="select-field">权重转入<select id="event-to">${familySelectOptions(r.familyWeights.map(x=>x.family),r.familyWeights[1].family)}</select></label></div>`:''}<div class="event-options">${(['a','b','c'] as const).map(k=>`<button class="event-option" data-action="event-choice" data-choice="${k}" ${r.nodeState.serviceUsed?'disabled':''}><span class="letter">${k.toUpperCase()}</span><div><b>${esc(e?.[`option_${k}`])}</b><p><span class="gold">代价：${esc(e?.[`option_${k}_cost`])}</span><br>${rule(e?.[`option_${k}_reward`]||'')}</p></div></button>`).join('')}</div></div></div>${serviceFooter()}</div>`}
function defeatReason(){if(!run)return '';if(run.hp<=0)return '守军突破耗尽了命匣。远征结束。';if(R.currentNode(run)?.kind==='boss')return `${run.battleResult?.duration&&run.battleResult.duration>=75?'进攻超时':'兵团被击退'}。首领三波必须连胜，仍有命匣也不能撤退。`;return run.battleResult?.message||'军团没能守住最后一道防线。'}
function endScreen(){const r=run!,won=r.phase==='victory';return `<div class="end-screen"><div class="eyebrow">${won?'第三章完结 · 王都改制成功':'本次远征结束 · 明天继续营业'}</div><h1>${won?'这座王都，换你来开张。':r.hp<=0?'命匣碎了。明天再开张。':'首领守住了城门。'}</h1><p class="muted" style="margin-top:12px">${won?'你把一盘盘随机的骨头，拼成了一支军队。':esc(defeatReason())}</p><div class="end-stats"><div class="end-stat"><b>${r.runStats.wavesWon}/36</b><span>胜利波次</span></div><div class="end-stat"><b>${r.runStats.spins}</b><span>招魂拉杆</span></div><div class="end-stat"><b>${r.runStats.unitsSummoned}</b><span>正式招募</span></div><div class="end-stat"><b>${r.ownedRelics.length}</b><span>遗物收藏</span></div></div><div class="row wrap" style="justify-content:center;margin-bottom:20px">${R.deployedUnits(r).map(u=>`<span class="badge rank-${getUnit(u.templateId).rank}">${esc(getUnit(u.templateId).name)} · R${getUnit(u.templateId).rank} Lv${levelForXp(u.xp)}</span>`).join('')}</div><div class="row wrap" style="justify-content:center">${btn('查看最后战报','battle-report',{},'compact')}${btn('换个思路，再开一局','title',{},'primary')}${btn('保留种子，重新挑战','replay-seed',{},'compact')}</div></div>`}
function showHelp(){currentModal='help';openModal('上岗指南：六步开张',`<div class="help-steps"><div class="help-step"><div><h3>先选路线，再进据点</h3><p>地图上的发光节点可以前往。普通据点稳妥，精英奖励更好，首领必须击败。</p></div></div><div class="help-step"><div><h3>每波有一次免费拉杆</h3><p>九格里，三横、三竖、两斜都能连线。同一族有几条线，只出一名对应阶级的职业：一线R1，两线R2，三线R3，四线R4。</p></div></div><div class="help-step"><div><h3>盘面先预览，可以动手脚</h3><p>初始止轮钮能锁一列、重摇其他两列，费用1骨。每盘总共最多两次干预，最后只收一次兵。其他改盘工具来自遗物和道具。</p></div></div><div class="help-step"><div><h3>把新兵安置好</h3><p>点兵牌，再点阵位，或直接拖动战场士兵。前排挡住敌人，远程与治疗放后排。上阵初始4名，可以用骨头扩到8名。</p></div></div><div class="help-step"><div><h3>重复兵也有用</h3><p>选想培养的兵，点击吸收，再选不要的供体。训练到4级选专精。训练不能改变出生阶级；抽到同族更高阶身体可用换壳保留训练。</p></div></div><div class="help-step"><div><h3>进攻、清点、再摇下一波</h3><p>战斗自动进行，正式士兵波后满血复起。突破防线会损失命匣。三波后拿一件遗物并选择下条路。到第三章击败王都首领即通关。</p></div></div></div>`,btn('知道了，去开张','close-modal',{},'primary'))}
function showSettings(){currentModal='settings';openModal('设置与远征存档',`<div class="settings-row"><div><strong>声音</strong><p>短促的拉杆、中奖和战斗提示</p></div>${btn(settings.muted?'开启声音':'静音','toggle-sound',{},'compact')}</div><div class="settings-row"><div><strong>音量</strong></div><input type="range" id="volume-input" min="0" max="0.6" step="0.02" value="${settings.volume}" aria-label="音量"/></div><div class="settings-row"><div><strong>战斗速度</strong><p>只改变播放速度，不改变战斗规则</p></div>${btn(`${settings.speed}× 切换`,'speed-settings',{},'compact')}</div><div class="settings-row"><div><strong>减少界面动画</strong><p>保留状态反馈，关闭循环装饰动画</p></div>${btn(settings.reduced?'已开启':'已关闭','toggle-motion',{},'compact')}</div><div class="settings-row"><div><strong>全屏</strong><p>快捷键 F；Esc退出</p></div>${btn('切换全屏','fullscreen',{},'compact')}</div><div class="settings-row"><div><strong>自动保存</strong><p>每次操作后保存，战斗中也定期保留进度。关闭页面后可在标题继续。</p></div><span class="badge success">${storageFailed?'保存受限':'已启用'}</span></div><div class="row wrap" style="margin-top:20px">${btn('导入存档','import-save',{},'compact')}</div>${run?`<div class="row wrap" style="margin-top:20px">${btn('导出存档','export-save',{},'compact')}${btn('保存并返回标题','title',{},'compact')}${btn('放弃本局并重开','confirm-new',{},'danger compact')}</div>`:''}`,btn('返回游戏','close-modal',{},'primary'))}
function showWeights(){const r=run!;currentModal='weights';openModal('你的招魂概率',`<p class="rule-text">九格各自独立抽样，使用相同权重。改变权重会同时影响横、竖、斜的连线机会。</p><div class="weight-list">${R.activeWeights(r).map(w=>`<div class="weight-row" style="${familyStyle(w.family)}">${familyIcon(w.family)}<strong>${FAMILY_NAMES[w.family]}</strong><span>${w.weight}/20</span><span>${w.weight*5}%</span></div>`).join('')}</div><div class="divider"></div><p class="rule-text">四族均为25%时，基础盘面至少中奖约41.01%，每盘平均产兵0.427名。偏重一族更容易出该族高阶，代价是其他族更难来。</p><p class="small muted" style="margin-top:12px">上面的基础概率不含遗物和改盘；没有隐藏保底。权重在黑市或邪术工坊调整。</p><div class="divider"></div><div class="row wrap">${[1,2,3,4].map(i=>`<span class="badge">${i}线 → ${RANK_NAMES[i]} R${i}</span>`).join('')}<span class="badge">满盘八线 → R4 Lv8</span></div>`,btn('明白了','close-modal',{},'primary'))}
function unitDetailBody(u:UnitInstance,interactive:boolean){const live=interactive&&run?.phase==='battle'?battle?.units.find(x=>x.sourceUid===u.uid):undefined;const d=getUnit(u.templateId),s=getStats(u),spec=specializationsFor(d.id).find(x=>x.choice===u.specialization),next=s.level<8?XP_THRESHOLDS[s.level]:150;return `<div class="unit-detail-head rank-${d.rank}" style="${familyStyle(d.family)}">${familyIcon(d.family)}<div><span class="rank-badge">${FAMILY_NAMES[d.family]} · ${RANK_NAMES[d.rank]} R${d.rank}</span><h3>${d.name}</h3><p>${d.role}${interactive?' · '+unitLocation(u):''} · 训练 Lv${s.level}${u.specialization?' · '+spec?.name:''}</p></div></div><div class="stats-grid">${[['生命',n(s.hp)],['攻击',n(s.atk)],['护甲',n(s.armor)],['攻速',s.aps.toFixed(2)+'/秒'],['暴击',pct(s.critRate)],['射程',s.range+'米'],['格挡',pct(s.blockRate)],['吸血',pct(s.lifesteal)]].map(([a,b])=>`<div class="stat">${a}<b>${b}</b></div>`).join('')}</div>${live?`<div class="tip-banner">${live.alive?'战内':'已倒地'} · 生命 ${n(live.hp)}/${n(live.maxHp)} · 护盾 ${n(live.shield)}${live.statuses.length?' · '+live.statuses.map(x=>STATUSES.find(y=>y.id===x.id)?.name||'增益').filter((v,i,a)=>a.indexOf(v)===i).join('、'):''}</div>`:''}<div class="row between"><span class="small muted">训练经验 ${u.xp}/${next}${s.level===8?' · 已满级':''}</span><span class="badge">出生阶级不随经验改变</span></div><section class="skill-block"><h3>主技能 · ${d.primary.name}</h3><p>${rule(d.primary.effect)}</p><p class="trigger">触发：${rule(d.primary.trigger)} · 内置间隔 ${d.primary.cooldown}秒</p></section><section class="skill-block"><h3>被动 · ${d.passive.name}</h3><p>${rule(d.passive.effect)}</p><p class="trigger">触发：${rule(d.passive.trigger)}</p></section>${spec?`<section class="skill-block"><h3>训练专精 · ${spec.name}</h3><p>${rule(spec.effect)}</p><p class="trigger">取舍：${rule(spec.tradeoff)}</p></section>`:`<section class="skill-block"><h3>Lv4 专精选择</h3><p>${specializationsFor(d.id).map(x=>`${x.choice} · ${x.name}：${rule(x.mechanical_change)}`).join('<br>')}</p>${interactive&&s.level>=4?btn('选择这个职业的专精','spec-dialog',{uid:u.uid},'primary compact'):''}</section>`}<section class="skill-block"><h3>怎样搭配</h3><p>需要：${rule(d.needs.join('、'))}<br>提供：${rule(d.provides.join('、'))}<br><span class="muted">弱点：${rule(d.weakness)}</span></p></section>`}
function showUnit(uid:string){const u=run?R.findUnit(run,uid):undefined;if(!u)return;selectedUid=uid;currentModal='unit';const manage=run!.phase!=='battle'&&run!.phase!=='waveResult';openModal('员工档案',unitDetailBody(u,true),`${manage?`${btn('同族换壳','fusion-dialog',{uid},'compact')}${btn('吸收其他兵','sacrifice-mode',{uid},'compact')}${btn('遣散','dismiss-dialog',{uid},'danger compact')}`:''}${btn('返回','close-modal',{},'primary')}`)}
function showTemplate(id:string){currentModal='template';openModal('职业图鉴',unitDetailBody(makeUnit(id,'preview'),false),btn('回到图鉴','codex',{},'primary'))}
function showSpec(uid:string){const u=run?R.findUnit(run,uid):undefined;if(!u)return;currentModal='spec';const d=getUnit(u.templateId);openModal(`${d.name} · 选择训练专精`,`<p class="rule-text" style="margin-bottom:20px">两条方向互斥。选择改变打法，不改变出生阶级；换到新职业时重新选择。</p><div class="spec-grid">${specializationsFor(d.id).map(s=>`<button class="spec-card" data-action="choose-spec" data-uid="${uid}" data-choice="${s.choice}"><span class="badge">方向 ${s.choice}</span><h3>${s.name}</h3><p>${rule(s.effect)}</p><p class="tradeoff">取舍：${rule(s.tradeoff)}</p><span class="gold small">选择这个专精 →</span></button>`).join('')}</div>`)}
function showSacrifice(donorUid:string,targetUid:string){const donor=R.findUnit(run!,donorUid),target=R.findUnit(run!,targetUid);if(!donor||!target)return;const d=getUnit(donor.templateId),t=getUnit(target.templateId),xp=[0,2,5,12,25][d.rank]+Math.floor(donor.xp*.75),nextXp=Math.min(150,target.xp+xp);currentModal='sacrifice';openModal('吸收预览：这名供体会消失',`<div class="sacrifice-preview"><div class="unit-detail-head" style="${familyStyle(d.family)}">${familyIcon(d.family)}<div><h3 style="font-size:var(--t3)">${d.name}</h3><p>供体 · ${unitLocation(donor)} · R${d.rank} Lv${levelForXp(donor.xp)}</p></div></div><div class="compare-arrow">→</div><div class="unit-detail-head" style="${familyStyle(t.family)}">${familyIcon(t.family)}<div><h3 style="font-size:var(--t3)">${t.name}</h3><p>受益者 · ${unitLocation(target)} · R${t.rank}</p></div></div></div><div class="confirm-summary">获得 ${nextXp-target.xp} 训练经验${xp>nextXp-target.xp?`，${xp-(nextXp-target.xp)} 溢出浪费`:''}。<br>训练 Lv${levelForXp(target.xp)} → Lv${levelForXp(nextXp)}；出生阶级仍为 R${t.rank}。<br>供体及其技能消失，不触发战内死亡效果。</div>`,`${btn('取消','cancel-sacrifice-dialog',{},'compact')}${btn('吸收这名供体','confirm-sacrifice',{donor:donorUid,target:targetUid},'danger')}`)}
function showFusion(uid:string){const old=R.findUnit(run!,uid);if(!old)return;const d=getUnit(old.templateId),bodies=allUnits().filter(u=>u.uid!==uid&&getUnit(u.templateId).family===d.family&&getUnit(u.templateId).rank>d.rank);currentModal='fusion';openModal('换壳：保留训练，换上高阶职业',`<p class="rule-text">${unitLocation(old)}的${d.name}保留训练与阵位。下面选中的高阶身体将被消耗，经验取两者较大值，技能改为新职业。没有额外献祭经验。</p><div class="divider"></div>${bodies.length?`<div class="stack">${bodies.map(u=>{const x=getUnit(u.templateId);return `<div class="row between"><div><strong>${x.name} · R${x.rank}</strong><p class="small gold">${unitLocation(u)} · 当前Lv${levelForXp(u.xp)} / ${u.xp}经验 · ${u.specialization?specializationsFor(u.templateId).find(s=>s.choice===u.specialization)?.name:'未选专精'}</p><p class="small muted">结果训练Lv${levelForXp(Math.max(old.xp,u.xp))}，旧职业技能不继承</p></div>${btn('消耗此身体换壳','confirm-fusion',{old:uid,body:u.uid},'primary compact')}</div>`}).join('')}</div>`:'<div class="empty">目前没有同族更高阶的身体。去老虎机追一次同族多线。</div>'}`,btn('返回','close-modal',{},'compact'))}
function showRelic(id:string){const d=getRelic(id),owned=run?.ownedRelics.includes(id),equipped=run?.machineRelics.includes(id)||run?.armyRelics.includes(id);currentModal='relic';openModal(d.name,`<div class="row between" style="margin-bottom:16px"><span class="badge">${d.type==='machine'?'机器零件':'军团遗物'} · ${rarityName(d.rarity)}</span><span class="gold">参考价 ${d.price} 骨</span></div><div class="skill-block"><h3>效果</h3><p>${rule(d.effect)}</p></div><div class="skill-block"><h3>什么时候触发</h3><p>${rule(d.trigger)}</p></div><div class="skill-block"><h3>限制</h3><p>${rule(d.limits)}</p></div><div class="skill-block"><h3>为什么不总是最优</h3><p>${rule(d.tradeoff)}</p></div>`,`${owned&&!equipped?btn('装备这件遗物','equip-dialog',{id},'primary'):equipped?'<span class="badge success">已装备</span>':''}${btn('返回','close-modal',{},'compact')}`)}
function showInventory(){if(!run)return;currentModal='inventory';openModal('你的军团',`<div class="row between" style="margin-bottom:16px"><span class="badge">上阵 ${R.deployedUnits(run).length}/${run.capacity} · 后备 ${R.reserveUnits(run).length}/8</span>${R.expansionCost(run)!==null?btn(`扩军 +1 · ${R.expansionCost(run)}骨`,'expand',{},'compact',run.bones<R.expansionCost(run)!):''}</div><div class="unit-grid">${allUnits().map(u=>`<button class="codex-unit rank-${getUnit(u.templateId).rank}" data-action="unit-info" data-uid="${u.uid}" style="${familyStyle(getUnit(u.templateId).family)}">${familyIcon(getUnit(u.templateId).family)}<div><span class="rank-badge">R${getUnit(u.templateId).rank} · Lv${levelForXp(u.xp)}</span><strong>${getUnit(u.templateId).name}</strong><p>${u.slot===null?'后备':'第'+(u.slot+1)+'阵位'}</p></div></button>`).join('')}</div><div class="divider"></div><div class="row between"><h3>遗物收藏</h3>${btn('管理装备','relic-inventory',{},'compact')}</div><div class="relic-equipped">${run.ownedRelics.map(id=>`<button data-action="relic-info" data-id="${id}">${run!.machineRelics.includes(id)||run!.armyRelics.includes(id)?'✓ ':''}${getRelic(id).name}</button>`).join('')}</div>`,btn('返回','close-modal',{},'primary'),true)}
function showRelicInventory(){if(!run)return;currentModal='relic-inventory';const r=run;openModal('遗物库与装备槽',`<p class="rule-text">机器 ${r.machineRelics.length}/${r.machineCapacity}，军团 ${r.armyRelics.length}/${r.armyRelicCapacity}。未装备的遗物保留在库里，可以在允许的阶段替换。</p><p class="small muted" style="margin-top:8px">机器配置在本节点首次拉杆后锁定；战斗期间所有装备锁定。</p><div class="divider"></div><div class="stack">${r.ownedRelics.map(id=>{const d=getRelic(id),equipped=r.machineRelics.includes(id)||r.armyRelics.includes(id);return `<div class="row between"><div><strong>${d.name}</strong><p class="small muted">${d.type==='machine'?'机器':'军团'} · ${rarityName(d.rarity)}</p></div><div class="row">${btn('详情','relic-info',{id},'ghost compact')}${equipped?'<span class="badge success">已装备</span>':btn('装备 / 替换','equip-dialog',{id},'compact')}</div></div>`}).join('')}</div>`,btn('返回','close-modal',{},'primary'))}
function showEquip(id:string){const d=getRelic(id),equipped=d.type==='machine'?run!.machineRelics:run!.armyRelics,cap=d.type==='machine'?run!.machineCapacity:run!.armyRelicCapacity;if(equipped.length<cap){act(()=>R.equipRelic(run!,id),{close:true});return}currentModal='equip';openModal('选择要替换的遗物',`<p class="rule-text">将${d.name}放入装备槽，被替换者保留在遗物库。</p><div class="stack" style="margin-top:20px">${equipped.map(old=>btn(`替换 ${getRelic(old).name}`,'equip-relic',{id,replace:old},'wide')).join('')}</div>`,btn('取消','close-modal',{},'compact'))}
function showClaim(){if(!run?.slot||run.slot.settled)return;const wins=R.getSlotWins(run);if(!wins.length){claim(false);return}for(const win of wins)if(!branchChoices[win.family]||!win.templateIds.includes(branchChoices[win.family]!))branchChoices[win.family]=win.templateIds[0];currentModal='claim';openModal(wins.some(w=>w.rank>=3)?'同源连响 · 更好的身体来了':'招魂结果 · 每个家族只出一名',`<div class="spin-results">${wins.map(w=>{const chosen=getUnit(branchChoices[w.family]||w.templateIds[0]);return `<section class="result-unit rank-${w.rank}" style="${familyStyle(w.family)}">${familyIcon(w.family)}<div><div class="row between"><span class="rank-badge">${w.lineCount}线 · ${RANK_NAMES[w.rank]} R${w.rank}</span><span class="badge new">只出 1 名</span></div><h3>${chosen.name}</h3><p class="small muted" style="margin-top:6px">出生训练 Lv${w.level} · ${w.lines.map(i=>PAYLINE_NAMES[i]).join(' + ')}</p>${w.templateIds.length>1?`<div class="branch-options">${w.templateIds.map(id=>{const d=getUnit(id);return `<button class="branch-option ${branchChoices[w.family]===id?'selected':''}" data-action="choose-branch" data-family="${w.family}" data-id="${id}"><b>${d.name}</b><p>${d.role}<br>${rule(d.primary.effect)}</p></button>`}).join('')}</div>`:`<p class="rule-text" style="margin-top:12px">${rule(chosen.primary.effect)}</p>`}</div></section>`}).join('')}</div><p class="small muted" style="margin-top:16px">高阶意味着新职业与更好的基础属性。经验只提升训练，不会让低阶兵沿这条树升阶。</p>`,`${btn('只招募到待命区','claim',{auto:'0'},'compact')}${btn('招募并补空阵位','claim',{auto:'1'},'primary')}`,true)}
function claim(auto:boolean){if(!run)return;const wins=R.getSlotWins(run),chosenNames=wins.map(w=>`${getUnit(branchChoices[w.family]||w.templateIds[0]).name} R${w.rank}`),result=R.claimSpin(run,branchChoices);if(!result.ok){toast(result.message||'领取失败',true);return}const newly=run.staging.map(u=>u.uid);if(auto)for(const uid of newly){const free=Array.from({length:run.capacity},(_,i)=>i).find(i=>!R.deployedUnits(run!).some(u=>u.slot===i));if(free===undefined)break;R.deployUnit(run,uid,free)}selectedUid=newly[0]||selectedUid;selectedTool=null;toolCells=[];branchChoices={};workbenchTab='army';closeModal();sound.play(wins.some(x=>x.rank>=3)?'jackpot':wins.length?'win':'confirm');toast(wins.length?`招募 ${chosenNames.join('、')}${run.staging.length?' · 请处理待命区':''}`:'空盘收起。旧军团仍在，可以追加或直接进攻。');persist();render()}
function showCodex(){currentModal='codex';let body=`<div class="row wrap" style="margin-bottom:20px">${[['units','职业图鉴'],['relics','遗物图鉴'],['builds','构筑灵感'],['rules','状态规则']].map(([id,label])=>btn(label,'codex-tab',{tab:id},codexTab===id?'primary compact':'compact')).join('')}</div>`;
 if(codexTab==='units')body+=`<div class="codex-families">${FAMILIES.map(f=>`<button class="btn compact ${codexFamily===f.id?'primary':''}" data-action="codex-family" data-family="${f.id}">${familyIcon(f.id,'sm')}${FAMILY_NAMES[f.id]}</button>`).join('')}</div><p class="rule-text" style="margin-bottom:16px">${esc(FAMILIES.find(f=>f.id===codexFamily)?.humor)} 同族的R2、R3各有两个职业，收兵时选择。</p><div class="codex-grid">${UNITS.filter(u=>u.family===codexFamily).map(u=>`<button class="codex-unit rank-${u.rank}" style="${familyStyle(u.family)}" data-action="template-info" data-id="${u.id}">${familyIcon(u.family)}<div><span class="rank-badge">${RANK_NAMES[u.rank]} R${u.rank}</span><strong>${u.name}</strong><p>${u.role}</p></div></button>`).join('')}</div>`;
 else if(codexTab==='relics')body+=`<div class="codex-grid">${RELICS.map(r=>`<button class="codex-unit" data-action="relic-info" data-id="${r.id}">${icon(r.type==='machine'?'wrench':'spark')}<div><span class="small gold">${rarityName(r.rarity)} · ${r.type==='machine'?'机器':'军团'}</span><strong>${r.name}</strong><p>${r.price} 骨 · 第${r.unlock_act}章解锁</p></div></button>`).join('')}</div>`;
 else if(codexTab==='builds')body+=`<div class="spec-grid">${BUILDS.map(b=>`<section class="spec-card"><h3>${b.name}</h3><p>${b.families.map(f=>FAMILY_NAMES[f as FamilyId]).join(' + ')}</p><p>${rule(b.formation)}</p><p class="small muted">优先：${b.priority_stats.join('、')}<br>弱点：${esc(b.counters)}</p><p class="tradeoff">${esc(b.slot_plan)}</p></section>`).join('')}</div>`;
 else body+=`<div class="stack">${STATUSES.map(s=>`<section class="skill-block"><h3>${s.name}</h3><p>${rule(s.stack_rule)}</p><p class="trigger">持续：${rule(s.duration)} · 上限：${rule(s.cap)}</p><p class="small muted">${rule(s.interaction)}</p></section>`).join('')}</div>`;
 openModal('白骨图鉴 · 点开任何不明白的东西',body,btn('返回游戏','close-modal',{},'primary'),true)
}
function showTemporaryUnit(id:string){const u=battle?.units.find(x=>x.id===id);if(!u)return;const owner=battle?.units.find(x=>x.id===u.ownerId);currentModal='temporary-unit';openModal(u.name,`<span class="badge new">临时召唤 · 本场战斗限定</span><div class="stats-grid">${[['生命',n(u.hp)+' / '+n(u.maxHp)],['攻击',n(u.atk)],['护甲',u.armor],['攻速',u.aps.toFixed(2)+'/秒']].map(([a,b])=>`<div class="stat">${a}<b>${b}</b></div>`).join('')}</div><p class="rule-text">${owner?'由'+esc(owner.name)+'召来。':''}${u.ttl?'剩余存在时间约'+Math.max(0,Math.ceil(u.ttl-u.age))+'秒。':''}<br>不会进入后备或成为永久士兵，也不会额外产生骨头或训练经验。</p>`,`${owner?.sourceUid?btn('查看召唤者','unit-info',{uid:owner.sourceUid},'compact'):''}${btn('返回战斗','close-modal',{},'primary')}`)}
function showEnemy(id:string,battleId?:string){let e;try{e=getEnemy(id)}catch{return}const live=battleId?battle?.units.find(u=>u.id===battleId):undefined;currentModal='enemy';openModal(e.name,`<div class="stats-grid">${[['生命',live?`${n(live.hp)} / ${n(live.maxHp)}`:e.hp],['攻击',live?Math.round(live.atk):e.atk],['护甲',live?live.armor:e.armor],['攻速',live?live.aps.toFixed(2):e.aps]].map(([a,b])=>`<div class="stat">${a}<b>${b}</b></div>`).join('')}</div><div class="skill-block"><h3>技能</h3><p>${rule(e.skill)}</p></div><div class="skill-block"><h3>如何应对</h3><p>${rule(e.counterplay)}</p></div><p class="small muted" style="margin-top:16px">${live?'当前战内属性，已包含节点修正。打开详情时战斗暂停。':'此处为基础模板数值；当前节点可能带有生命或攻击修正。'}</p>`,btn('返回','close-modal',{},'primary'))}
function showEnemyPreview(){if(!run)return;const node=R.currentNode(run)!;currentModal='enemy-preview';openModal('三波敌情 · 可以提前做准备',`<div class="stack">${node.waves.map((wave,i)=>`<section class="skill-block"><h3>第${i+1}波${i+1===run!.wave?' · 当前波':''}</h3><div class="row wrap" style="margin-top:12px">${wave.map(e=>btn(`${getEnemy(e.templateId).name} ×${e.count}`,'enemy-info',{id:e.templateId},'compact')).join('')}</div><p class="small muted" style="margin-top:12px">${wave.map(e=>getEnemy(e.templateId).threat).join('；')}</p></section>`).join('')}</div><p class="small muted" style="margin-top:16px">${node.kind==='boss'?'首领节点任意一波失败，远征结束。':'超时会撤出当前节点，失去尚未获得的奖励。'} 普通敌人突破损命匣2，精英据点4，首领本体10；每波最多损失20。</p>`,btn('回去布阵','close-modal',{},'primary'),true)}
function comboLabel(id:string){const [owner,effect]=id.split(':');const u=UNITS.find(x=>x.id===owner);if(u){if(effect==='P'||effect==='primary')return u.primary.name;if(effect==='V')return u.passive.name;if(effect==='blink')return '绕后刺杀';const r=RELICS.find(x=>x.id===effect);if(r)return r.name}const enemy=ENEMIES.find(x=>x.id===owner);if(enemy)return enemy.name+({skill:'技能',telegraph:'蓄力预警',buff:'战场增援'}[effect]||'技能');const labels:Record<string,string>={'corpse:consume':'消耗尸骸','enemy:reinforcement':'敌军增援','haste:gain':'获得急速','chill:freeze':'寒滞凝冰','item:corpseExplosion':'骨灰引爆','poison:cashout':'尸毒引爆','shock:consume':'电荷放电','wet:chill':'潮湿助冻','wet:extinguish':'潮湿灭焰'};const relic=RELICS.find(r=>r.id===id);const status=STATUSES.find(s=>s.id===id);return esc(labels[id]||relic?.name||status?.name||'战场连锁')}
function comboEntries(counts:Record<string,number>){return Object.entries(counts).filter(([id])=>!id.endsWith(':primary')&&!id.startsWith('E')).sort((a,b)=>b[1]-a[1])}
function showBattleReport(){const s=run?.battleResult;if(!s){toast('当前还没有一场完整战斗的战报');return}currentModal='report';const units=Object.values(s.stats.unitStats).sort((a,b)=>b.damage-a.damage);openModal('这场战斗，究竟发生了什么',`<div class="stats-grid">${[['总伤害',n(s.stats.damage)],['有效治疗',n(s.stats.healing)],['提供护盾',n(s.stats.shield)],['临时召唤',s.stats.summons],['尸毒伤害',n(s.stats.poisonDamage)],['爆葬伤害',n(s.stats.explosionDamage)],['暴击次数',s.stats.crits],['击倒敌人',s.stats.kills]].map(([a,b])=>`<div class="stat">${a}<b>${b}</b></div>`).join('')}</div><div class="divider"></div><h3>员工贡献</h3><div class="stack" style="margin-top:16px">${units.map(u=>`<div class="row between"><strong>${esc(u.name)}</strong><span class="small muted">${n(u.damage)}伤害 · ${n(u.healing)}治疗 · ${n(u.shield)}护盾 · ${u.summons}召唤</span></div>`).join('')}</div><div class="divider"></div><h3>发生的连锁</h3><div class="combo-strip">${comboEntries(s.stats.comboCounts).slice(0,24).map(([id,count])=>`<span>${comboLabel(id)} ×${count}</span>`).join('')||'<span>这场战斗还没有形成明显的技能链。</span>'}</div><p class="small muted" style="margin-top:16px">治疗只统计实际恢复的生命。临时单位的贡献在战内统计，不会变成永久经验或额外骨头。</p>`,btn('返回','close-modal',{},'primary'),true)}
function showItem(id:string){if(!run)return;const d=getItem(id);if(['I03','I04','I05'].includes(id)){closeModal();workbenchTab='army';selectedTool=R.interventionOptions(run).find(x=>x.sourceId===id)||null;toolCells=[];render();if(selectedTool&&!selectedTool.available)toast(selectedTool.reason||'现在不能使用',true);return}currentModal='item';const needsTarget=!['I01','I02','I10'].includes(id);openModal(d.name,`<p class="rule-text">${rule(d.effect)}</p><p class="small muted" style="margin:12px 0 20px">${rule(d.limit)}</p>${id==='I01'?`<label class="select-field">为哪个家族准备引魂券<select id="item-family">${familySelectOptions(run.familyWeights.map(x=>x.family))}</select></label>`:''}${needsTarget?`<label class="select-field">使用目标<select id="item-target">${unitSelectOptions(selectedUid)}</select></label>`:''}`,`${btn('取消','close-modal',{},'compact')}${btn('使用一份','use-item',{id},'primary')}`)}
function showCombatItems(){if(!run)return;currentModal='combat-items';openModal('战中道具 · 本波最多一份',`<div class="stack">${['I11','I12'].filter(id=>(run!.items[id]||0)>0).map(id=>`<div class="row between"><div><strong>${getItem(id).name} ×${run!.items[id]}</strong><p class="small muted">${rule(getItem(id).effect)}</p></div>${btn('选择目标','item-dialog',{id},'compact')}</div>`).join('')}</div>`,btn('返回战斗','close-modal',{},'primary'))}
function showTempWeight(){if(!run)return;currentModal='temp-weight';openModal('偏心配重 · 只影响这个节点',`<p class="rule-text">在本节点第一次拉杆前，把2份权重从一族移给另一族；离开节点后自动还原。</p><div class="form-row" style="margin-top:20px"><label class="select-field">转出<select id="temp-from">${familySelectOptions(run.familyWeights.map(x=>x.family))}</select></label><label class="select-field">转入<select id="temp-to">${familySelectOptions(run.familyWeights.map(x=>x.family),run.familyWeights[1].family)}</select></label></div>`,`${btn('取消','close-modal',{},'compact')}${btn('设置本节点配重','apply-temp-weight',{},'primary')}`)}
function newRun(){closeModal();run=R.createRun(seedDraft,starterId);battle=null;paused=false;selectedUid='';mapSelection='';viewAct=1;workbenchTab='army';selectedTool=null;toolCells=[];sacrificeTarget='';lastFxId=0;spinningMs=0;persist();sound.play('travel');render()}
function continueRun(){const text=localStorage.getItem(SAVE_KEY);const loaded=text?R.deserializeRun(text):null;if(!loaded){toast('存档无法读取。原文件没有被覆盖，可以新开一局。',true);return}run=loaded;viewAct=run.act;battle=run.phase==='battle'?(run.battleSnapshot||createBattle(R.getCombatInput(run))):null;paused=false;accumulator=0;lastFxId=0;closeModal();render();toast('远征已恢复，骨头和盘面仍在。')}
function toTitle(){persist();run=null;battle=null;paused=false;spinningMs=0;selectedTool=null;sacrificeTarget='';closeModal();savedPreview=savedText?R.deserializeRun(savedText):null;render()}
function spin(){if(!run||spinningMs>0)return;const result=R.spin(run);if(!result.ok){toast(result.message||'无法拉杆',true);return}sound.play('spin');selectedTool=null;toolCells=[];branchChoices={};spinningMs=settings.reduced?60:680;spinVisualTick=-1;persist();render()}
function startBattle(){if(!run)return;const result=R.startWave(run);if(!result.ok){toast(result.message||'还没准备好',true);return}battle=createBattle(R.getCombatInput(run));newestToast++;$('#toast-area').innerHTML='';paused=false;lastFxId=0;selectedTool=null;toolCells=[];sacrificeTarget='';spinningMs=0;closeModal();sound.play('travel');persist();render()}
function clickSlot(index:number){if(!run||!selectedTool||spinningMs>0)return;if(!selectedTool.available){toast(selectedTool.reason||'本盘不能再用这个工具',true);return}const kind=selectedTool.kind;let action:SlotIntervention|null=null;
 if(kind==='lockColumn'||kind==='rotateColumn')action={kind,index:index%3};
 else if(kind==='rerollCell')action={kind,index};
 else if(kind==='rerollRow')action={kind,index:Math.floor(index/3)};
 else if(kind==='rotateCorners')action={kind};
 else if(kind==='copyCenter'){action={kind:'copy',a:index,b:4}}
 else if(kind==='swapColumns'){if(!toolCells.length){toolCells=[index];render();return}action={kind,a:toolCells[0]%3,b:index%3}}
 else if(kind==='copy'||kind==='swap'){if(!toolCells.length){toolCells=[index];render();return}action={kind,a:toolCells[0],b:index}}
 if(!action)return;const source=selectedTool.sourceId;const result=act(()=>R.intervene(run!,action!,source),{silent:true});toolCells=[];selectedTool=null;render();if(result?.ok){sound.play('confirm');toast('盘面已改。确认后只结算最终这一盘。')}
}
function autoDeploy(uid:string){if(!run)return;const free=Array.from({length:run.capacity},(_,i)=>i).find(i=>!R.deployedUnits(run!).some(u=>u.slot===i));if(free===undefined){toast('上阵已满。可扩军、先换下一个单位，或存入后备。',true);return}act(()=>R.deployUnit(run!,uid,free))}
function exportSave(){if(!run)return;const blob=new Blob([R.serializeRun(run,battle&&run.phase==='battle'?battle:undefined)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`白骨开张-存档-${run.seed}.json`;a.click();URL.revokeObjectURL(url);toast('存档已导出')}
function toggleFullscreen(){if(document.fullscreenElement)void document.exitFullscreen();else void document.documentElement.requestFullscreen().catch(()=>toast('当前窗口不允许全屏',true))}

document.addEventListener('click',event=>{
 const el=(event.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!el||el instanceof HTMLButtonElement&&el.disabled)return;
 sound.unlock();const a=el.dataset.action,d=el.dataset;const val=(id:string)=>document.querySelector<HTMLSelectElement|HTMLInputElement>('#'+id)?.value||'';
 switch(a){
  case 'noop':break;
  case 'select-starter':seedDraft=val('seed-input')||seedDraft;starterId=d.id as R.StarterId;sound.play('click');render();break;
  case 'new-run':seedDraft=val('seed-input').trim()||seedDraft;if(savedPreview&&!['victory','defeat'].includes(savedPreview.phase)){openModal('开始新远征？','<p class="rule-text">这会替换浏览器中的当前存档。旧远征可先继续并导出存档。</p>',`${btn('取消','close-modal',{},'compact')}${btn('开始新远征','confirm-start',{},'primary')}`)}else newRun();break;
  case 'confirm-start':newRun();break;
  case 'continue-run':continueRun();break;
  case 'close-modal':closeModal();break;
  case 'title':toTitle();break;
  case 'replay-seed':seedDraft=run?.seed||seedDraft;starterId=run?.starterId||starterId;newRun();break;
  case 'help':showHelp();break;
  case 'settings':showSettings();break;
  case 'toggle-sound':settings.muted=!settings.muted;sound.muted=settings.muted;localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));showSettings();break;
  case 'toggle-motion':settings.reduced=!settings.reduced;persist();render();showSettings();break;
  case 'speed-settings':settings.speed=settings.speed===1?2:1;persist();render();showSettings();break;
  case 'speed':settings.speed=settings.speed===1?2:1;persist();render();break;
  case 'fullscreen':toggleFullscreen();break;
  case 'pause':paused=!paused;render();break;
  case 'confirm-new':openModal('放弃这次远征？','<p class="rule-text">当前军队、骨头和路线进度会被新的远征替换。</p>',`${btn('保留远征','close-modal',{},'compact')}${btn('放弃并重开','confirm-start',{},'danger')}`);break;
  case 'export-save':exportSave();break;
  case 'import-save':$('#save-file-input').click();break;
  case 'confirm-import':if(importedRun){run=importedRun;importedRun=null;viewAct=run.act;battle=run.phase==='battle'?run.battleSnapshot:null;paused=false;accumulator=0;lastFxId=0;selectedUid='';selectedTool=null;sacrificeTarget='';spinningMs=0;closeModal();persist();render();toast('存档已导入，远征继续。')}break;
  case 'view-act':viewAct=Number(d.act);mapSelection='';render();break;
  case 'inspect-node':mapSelection=d.id!;sound.play('click');render();break;
  case 'enter-node':if(run){battle=null;selectedUid='';selectedTool=null;sacrificeTarget='';act(()=>R.chooseNode(run!,d.id!));viewAct=run.act}break;
  case 'spin':spin();break;
  case 'claim-dialog':showClaim();break;
  case 'choose-branch':branchChoices[d.family as FamilyId]=d.id!;showClaim();break;
  case 'claim':claim(d.auto==='1');break;
  case 'select-tool':if(run){selectedTool=R.interventionOptions(run).map(uiTool).find(x=>x.sourceId===d.source)||null;toolCells=[];sound.play('click');render()}break;
  case 'cancel-tool':selectedTool=null;toolCells=[];render();break;
  case 'slot-cell':clickSlot(Number(d.index));break;
  case 'weights-info':showWeights();break;
  case 'select-unit':selectUnit(d.uid!);sound.play('click');break;
  case 'deploy-selected':if(selectedUid&&run)act(()=>R.deployUnit(run!,selectedUid,Number(d.slot)));else toast('先选择一张兵牌，再点空阵位。');break;
  case 'auto-deploy':autoDeploy(d.uid!);break;
  case 'bench':if(run)act(()=>R.benchUnit(run!,d.uid!),{close:true});break;
  case 'tab':workbenchTab=d.tab!;sacrificeTarget='';render();break;
  case 'unit-info':showUnit(d.uid!);break;
  case 'template-info':showTemplate(d.id!);break;
  case 'spec-dialog':showSpec(d.uid!);break;
  case 'choose-spec':if(run)act(()=>R.chooseSpecialization(run!,d.uid!,d.choice as 'A'|'B'),{close:true});break;
  case 'sacrifice-mode':sacrificeTarget=d.uid!;selectedUid=d.uid!;workbenchTab='army';closeModal();render();toast('现在选择要吸收掉的供体。确认前不会删除任何兵。');break;
  case 'cancel-sacrifice':sacrificeTarget='';render();break;
  case 'cancel-sacrifice-dialog':closeModal();sacrificeTarget='';render();break;
  case 'confirm-sacrifice':if(run){const res=act(()=>R.sacrifice(run!,d.donor!,d.target!),{close:true});if(res?.ok){selectedUid=d.target!;sacrificeTarget='';render()}}break;
  case 'fusion-dialog':showFusion(d.uid!);break;
  case 'confirm-fusion':if(run)act(()=>R.fuseBodies(run!,d.old!,d.body!),{close:true});break;
  case 'dismiss-dialog':if(run){const u=R.findUnit(run,d.uid!);if(u)openModal('遣散这名亡灵？',`<p class="rule-text">${getUnit(u.templateId).name}会永久离开，不获得骨头或经验。若想保留价值，请用吸收。</p>`,`${btn('保留','close-modal',{},'compact')}${btn('确认遣散','dismiss',{uid:d.uid!},'danger')}`)}break;
  case 'dismiss':if(run)act(()=>R.dismissUnit(run!,d.uid!),{close:true});break;
  case 'expand':if(run){const was=currentModal;act(()=>R.expandCapacity(run!));if(was==='inventory')showInventory()}break;
  case 'start-battle':startBattle();break;
  case 'continue-wave':if(run){act(()=>R.continueAfterWave(run!));if(run.phase==='prep'){battle=null;selectedTool=null;toolCells=[];selectedUid='';render()}viewAct=run.act}break;
  case 'take-reward':if(run){const res=act(()=>R.chooseReward(run!,d.id!));if(res?.ok){battle=null;viewAct=run.act;mapSelection='';render();if(run.phase==='victory')sound.play('victory')}}break;
  case 'inventory':showInventory();break;
  case 'relic-inventory':showRelicInventory();break;
  case 'relic-info':showRelic(d.id!);break;
  case 'equip-dialog':showEquip(d.id!);break;
  case 'equip-relic':if(run)act(()=>R.equipRelic(run!,d.id!,d.replace),{close:true});break;
  case 'item-dialog':showItem(d.id!);break;
  case 'cancel-queued-items':if(run)act(()=>R.cancelQueuedItems(run!));break;
  case 'use-item':if(run){const options:R.ItemUseOptions={uid:val('item-target')||undefined,family:(val('item-family')||undefined) as FamilyId|undefined,battle:battle||undefined};act(()=>R.useItem(run!,d.id!,options),{close:true})}break;
  case 'combat-items':showCombatItems();break;
  case 'buy':if(run)act(()=>R.buyShop(run!,d.id!));break;
  case 'refresh-shop':if(run)act(()=>R.refreshShop(run!));break;
  case 'shop-weight':if(run)act(()=>R.transferWeight(run!,val('shop-from') as FamilyId,val('shop-to') as FamilyId));break;
  case 'grave-heal':if(run)act(()=>R.restAtGrave(run!,'heal'));break;
  case 'grave-train':if(run)act(()=>R.restAtGrave(run!,'train',val('grave-target')));break;
  case 'apply-weights':if(run){const weights=[...document.querySelectorAll<HTMLInputElement>('.weight-input')].map(input=>({family:input.dataset.family as FamilyId,weight:Number(input.value)}));act(()=>R.reconfigureWeights(run!,weights))}break;
  case 'replace-family':if(run)act(()=>R.replaceFamily(run!,val('family-from') as FamilyId,val('family-to') as FamilyId));break;
  case 'event-choice':if(run)act(()=>R.chooseEvent(run!,d.choice as 'a'|'b'|'c',val('event-target')||undefined,{from:(val('event-from')||undefined) as FamilyId|undefined,to:(val('event-to')||undefined) as FamilyId|undefined}));break;
  case 'leave-service':if(run){act(()=>R.leaveService(run!));mapSelection='';render()}break;
  case 'temp-weight':showTempWeight();break;
  case 'apply-temp-weight':if(run)act(()=>R.transferWeight(run!,val('temp-from') as FamilyId,val('temp-to') as FamilyId,2,'relic'),{close:true});break;
  case 'enemy-preview':showEnemyPreview();break;
  case 'enemy-info':showEnemy(d.id!);break;
  case 'battle-report':showBattleReport();break;
  case 'codex':showCodex();break;
  case 'codex-tab':codexTab=d.tab!;showCodex();break;
  case 'codex-family':codexFamily=d.family as FamilyId;showCodex();break;
 }
});
$('#save-file-input').addEventListener('change',async event=>{const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>4000000)throw Error('存档超过4MB限制');const loaded=R.deserializeRun(await file.text());if(!loaded)throw Error('这份存档格式损坏或版本不匹配');importedRun=loaded;currentModal='import';openModal('载入这份远征存档？',`<p class="rule-text">种子 ${esc(loaded.seed)}<br>第${loaded.act}章 · 已过${loaded.runStats.wavesWon}波 · ${loaded.bones}骨头</p><p class="small muted" style="margin-top:12px">载入后将替换这个浏览器当前保存的远征。</p>`,`${btn('取消','close-modal',{},'compact')}${btn('载入存档','confirm-import',{},'primary')}`)}catch(e){toast(e instanceof Error?e.message:'无法读取存档',true)}input.value=''});
document.addEventListener('input',event=>{const target=event.target as HTMLInputElement;if(target.id==='seed-input')seedDraft=target.value;if(target.id==='volume-input'){settings.volume=Number(target.value);sound.volume=settings.volume;localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings))}if(target.classList.contains('weight-input')){const sum=[...document.querySelectorAll<HTMLInputElement>('.weight-input')].reduce((s,e)=>s+Number(e.value),0);$('#weight-total').textContent=`合计${sum}份 · ${sum===20?'配重合法':'需要恰好20份'}`;$('#weight-total').className=sum===20?'small success-text':'small danger-text';const p=document.querySelector(`[data-weight-pct="${target.dataset.family}"]`);if(p)p.textContent=Number(target.value)*5+'%'}});
document.addEventListener('keydown',event=>{if(event.target instanceof HTMLInputElement||event.target instanceof HTMLSelectElement||event.target instanceof HTMLTextAreaElement)return;if(event.code==='KeyF'){event.preventDefault();toggleFullscreen()}if(event.code==='Escape'){if(modalOpen)closeModal();else if(selectedTool){selectedTool=null;toolCells=[];render()}else if(sacrificeTarget){sacrificeTarget='';render()}else if(run?.phase==='battle'){paused=!paused;render()}}if(event.code==='Space'&&!modalOpen){event.preventDefault();if(run?.phase==='battle'){paused=!paused;render()}else if(run?.phase==='prep'){if(run.slot&&!run.slot.settled)showClaim();else if(R.canStartWave(run).ok)startBattle();else spin()}else if(run?.phase==='waveResult')act(()=>R.continueAfterWave(run!))}});
$('#modal-layer').addEventListener('click',event=>{if(event.target===$('#modal-layer'))closeModal()});
document.addEventListener('dragstart',event=>{const el=(event.target as HTMLElement).closest<HTMLElement>('[data-drag-unit]');if(el&&event.dataTransfer){event.dataTransfer.setData('text/plain',el.dataset.dragUnit!);event.dataTransfer.effectAllowed='move';selectedUid=el.dataset.dragUnit!}});
$('#stage').addEventListener('dragover',event=>{if(run?.phase==='prep'){event.preventDefault();if(event.dataTransfer)event.dataTransfer.dropEffect='move'}});
$('#stage').addEventListener('drop',event=>{event.preventDefault();if(run?.phase!=='prep')return;const uid=event.dataTransfer?.getData('text/plain');const slot=renderer.slotAtClient(event.clientX,event.clientY);if(uid&&slot!==null)act(()=>R.deployUnit(run!,uid,slot))});
window.addEventListener('beforeunload',persist);
window.addEventListener('resize',()=>renderer.resize());

function update(ms:number){
 if(spinningMs>0){spinningMs=Math.max(0,spinningMs-ms);if(spinningMs>0&&!settings.reduced&&run?.slot&&run.phase==='prep'){const tick=Math.floor((680-spinningMs)/65);if(tick!==spinVisualTick){spinVisualTick=tick;document.querySelectorAll<HTMLElement>('.slot-cell').forEach((cell,i)=>{const moving=spinningMs>(2-i%3)*135;const f=moving?run!.familyWeights[(tick+i*3)%4].family:run!.slot!.board[i];cell.innerHTML=familyIcon(f)+`<span class="cell-position">${i+1}</span>`;cell.classList.toggle('spinning',moving)})}}if(spinningMs===0){const wins=run?R.getSlotWins(run):[];if(wins.length)sound.play(wins.some(w=>w.rank>=3)?'jackpot':'win');render()}}
 if(run?.phase==='battle'&&battle&&!paused&&!modalOpen){
  accumulator+=ms/1000*settings.speed;
  let guard=0;while(accumulator>=1/60&&guard++<18000&&run.phase==='battle'){stepBattle(battle,1/60);accumulator-=1/60;if(battle.result){const outcome=battle.result;R.finishWave(run,battle);paused=false;accumulator=0;persist();sound.play(outcome==='win'?'win':'defeat');render();break}}
  const newFx=battle.effects.filter(e=>e.id>lastFxId);if(newFx.length){lastFxId=Math.max(...newFx.map(e=>e.id));if(newFx.some(e=>e.kind==='crit'))sound.play('hit');else if(newFx.some(e=>e.kind==='heal'))sound.play('heal');else if(newFx.some(e=>e.kind==='hit'))sound.play('hit')}
 }
 setStage();
}
let lastFrame=performance.now();
function frame(now:number){const delta=Math.min(80,now-lastFrame);lastFrame=now;update(delta);if(run?.phase==='battle'&&now-lastLiveRefresh>180){lastLiveRefresh=now;renderOverlay();const hp=$('#hud-hp');if(hp&&battle)hp.innerHTML=`${n(battle.phylacteryHp)}<span> / ${run.maxHp}</span>`;if(battle){const damage=$('#live-damage'),heal=$('#live-heal'),summons=$('#live-summons');if(damage)damage.textContent=n(battle.stats.damage);if(heal)heal.textContent=n(battle.stats.healing);if(summons)summons.textContent=String(battle.stats.summons)}}if(run?.phase==='battle'&&now-lastSaveTime>2500){lastSaveTime=now;persist()}requestAnimationFrame(frame)}

declare global {interface Window {render_game_to_text:()=>string;advanceTime:(ms:number)=>void;__whitebone?:{getRun:()=>R.RunState|null;getBattle:()=>BattleState|null;rendererStats:()=>unknown;actions:typeof R}}}
window.render_game_to_text=()=>JSON.stringify({mode:run?.phase||'title',modal:modalOpen?currentModal:null,seed:run?.seed,act:run?.act,node:run?R.currentNode(run)?.name:null,wave:run?.wave,hp:run?.phase==='battle'&&battle?battle.phylacteryHp:run?.hp,bones:run?.bones,capacity:run?.capacity,selectedUid,army:run?allUnits().map(u=>({uid:u.uid,id:u.templateId,name:getUnit(u.templateId).name,rank:getUnit(u.templateId).rank,level:levelForXp(u.xp),xp:u.xp,specialization:u.specialization,slot:u.slot,staged:run!.staging.some(s=>s.uid===u.uid)})):[],slot:run?.slot?{board:run.slot.board,settled:run.slot.settled,interventions:run.slot.interventions,wins:R.getSlotWins(run).map(w=>({family:w.family,lines:w.lineCount,rank:w.rank,level:w.level,units:1}))}:null,spinCost:run?R.spinCost(run):null,canStart:run?R.canStartWave(run):null,availableNodes:run?R.availableNodes(run).map(x=>({id:x.id,kind:x.kind,name:x.name})):[],weights:run?R.activeWeights(run):[],relics:run?{machine:run.machineRelics,army:run.armyRelics,owned:run.ownedRelics}:null,items:run?.items,battle:battle?{coordinateSystem:'origin top-left; x 0..40 meters rightwards; y 0..12 downwards',time:battle.time,result:battle.result,paused:paused||modalOpen,units:battle.units.filter(u=>u.alive).map(u=>({id:u.id,name:u.name,side:u.side,x:+u.x.toFixed(2),y:+u.y.toFixed(2),hp:+u.hp.toFixed(1),shield:+u.shield.toFixed(1),temporary:u.temporary,statuses:u.statuses.map(s=>s.id)})),corpses:battle.corpses.filter(c=>!c.consumed).length,stats:battle.stats}:null,runStats:run?.runStats});
window.advanceTime=(ms:number)=>{update(Math.max(0,Math.min(ms,180000)));if(run?.phase==='battle')renderOverlay();setStage()};
if(new URLSearchParams(location.search).has('test'))window.__whitebone={getRun:()=>run,getBattle:()=>battle,rendererStats:()=>renderer.getDebugStats(),actions:R};
render();requestAnimationFrame(frame);
